pub(super) fn lookup(language: usize, ru: &str, en: &str) -> Option<&'static str> {
    let index = KEYS.binary_search_by(|key| key.0.cmp(en).then_with(|| key.1.cmp(ru))).ok()?;
    VALUES.get(language)?.get(index).copied()
}
